    getOptions(type) {
      switch (type) {
        case 'days':
          return this.daysOfWeek.map(day => ({
            value: day.value,
            label: day.label
          }));
        case 'periods':
          return this.formData.periods.map(p => ({
            value: p.name,
            label: p.name
          }));
        case 'teachers':
          return this.formData.teachers.map(t => ({
            value: t.name,
            label: t.name
          }));
        case 'students':
          return this.formData.students.map(s => ({
