            label: s.name
          }));
        case 'subjects':
          return this.formData.subjects.map(s => ({
            value: s.name,
            label: s.name
          }));
        case 'rooms':
          return this.formData.rooms.map(r => ({
            value: r.name,
            label: r.name
          }));
        default:
          return [];
      }
    },
    getConstraintLabel(type) {
      // Recherche récursive dans la structure des contraintes
      const findLabel = (groups, searchType) => {
        for (const group of Object.values(groups)) {
          for (const item of group) {
            if (item.value === searchType) return item.label;
            if (item.children) {
              for (const child of item.children) {
                if (child.value === searchType) return child.label;
              }
            }
          }
        }
        return type;
      };
      return findLabel(this.constraintGroups, type);
