        'maxHours': 'Heures max',
        'minHours': 'Heures min',
        'startHour': 'Heure début',
        'endHour': 'Heure fin',
        'firstSlot': 'Premier créneau',
        'secondSlot': 'Second créneau',
        'maxGaps': 'Trous max',
        'maxSpan': 'Plage max',
        'minResting': 'Repos min',
        'allowEmpty': 'Jours vides autorisés',
        'allowException': 'Exception autorisée',
        'circular': 'Circulaire'
      };
      return keyMap[key] || key;
