    openConstraintModal() {
      const constraintType = this.selectedConstraintType;
      const constraintConfig = this.findConstraintConfig(constraintType);
      if (!constraintConfig) return;
      this.constraintForm = {
        type: constraintType,
        title: `Ajouter une contrainte: ${this.getConstraintLabel(constraintType)}`,
        fields: constraintConfig.fields,
        data: this.initializeConstraintData(constraintConfig.fields)
      };
      this.constraintModal.show();
    },
    findConstraintConfig(type) {
      // Recherche récursive dans la structure des contraintes
      for (const group of Object.values(this.constraintGroups)) {
        for (const item of group) {
          if (item.value === type) return item;
          if (item.children) {
            for (const child of item.children) {
              if (child.value === type) return child;
            }
          }
        }
      }
      return null;
    },
    initializeConstraintData(fields) {
      const data = {};
      fields.forEach(field => {
        if (field.type === 'multiple') {
          data[field.name] = [this.createPeriodItem(field.fields)];
        } else if (field.type === 'object') {
          data[field.name] = this.createObjectItem(field.fields);
        } else {
          data[field.name] = field.type === 'boolean' ? false : '';
        }
      });
      return data;
    },
    createPeriodItem(fields = null) {
      if (fields) {
        const item = {};
        fields.forEach(field => {
          if (field.type === 'select') {
            const options = this.getOptions(field.options);
            item[field.name] = options[0]?.value || '';
          } else {
            item[field.name] = '';
          }
        });
        return item;
      }
      return {
        day: this.formData.selectedDays[0] || '',
        hour: this.formData.periods[0]?.name || ''
      };
    },
    createObjectItem(fields) {
      const item = {};
      fields.forEach(field => {
        if (field.type === 'select') {
          const options = this.getOptions(field.options);
          item[field.name] = options[0]?.value || '';
        } else {
          item[field.name] = '';
        }
      });
      return item;
    },
    addPeriod(fieldName) {
      const fieldConfig = this.constraintForm.fields.find(f => f.name === fieldName);
      if (fieldConfig) {
        this.constraintForm.data[fieldName].push(this.createPeriodItem(fieldConfig.fields));
      }
    },
    removePeriod(fieldName, index) {
      if (this.constraintForm.data[fieldName].length > 1) {
        this.constraintForm.data[fieldName].splice(index, 1);
      }
    },
    saveConstraint() {
      this.formData.contraintes.push({
        type: this.constraintForm.type,
        ...this.constraintForm.data
      });
      this.constraintModal.hide();
      this.selectedConstraintType = '';
    },
    removeConstraint(index) {
      this.formData.contraintes.splice(index, 1);
    }
  }
